// Üretilen dosya: tool/ozgun/uret.py. Tarih · Osmanlı kültür ve kurumları: saray, ordu, ilmiye, vakıflar, gündelik hayat (kolay).
const ozHistory13Kolay = <(String, String, List<String>, String)>[
  ('Topkapı Sarayı\'na dışarıdan girişi sağlayan ve "Saltanat Kapısı" olarak da anılan ana kapı hangisidir?', 'Bâb-ı Hümâyûn', ['Bâbüsselâm', 'Bâbüssaâde', 'Bâb-ı Seraskeri'], 'Topkapı\'nın dış duvarındaki ana giriş Bâb-ı Hümâyûn\'dur. Bâbüsselâm ikinci avluya, Bâbüssaâde ise Enderun\'a açılır; Bâb-ı Âli ise sadrazam kapısıdır.'),
  ('Bir devlet görevlisi, Divan Meydanı\'ndan padişahın iç hizmetlerinin ve Enderun\'un bulunduğu üçüncü avluya geçmek istiyor. Hangi kapıdan geçmesi gerekir?', 'Bâbüssaâde (Akağalar Kapısı)', ['Bâb-ı Hümâyûn (Saltanat Kapısı)', 'Orta Kapı (Bâbüsselâm)', 'Bâb-ı Âli'], 'Üçüncü avluya açılan kapı Bâbüssaâde\'dir ve Akağalar Kapısı da denir. Bu kapıdan yalnız padişahın izin verdiği kişiler geçebilirdi.'),
  ('Yeni tahta çıkan bir padişahın karşısında devlet erkânı sırayla biat edecektir. Padişahın tahtı Topkapı Sarayı\'nda nerede kurulur?', 'Bâbüssaâde önünde', ['Bâb-ı Hümâyûn önünde', 'Orta Kapı\'nın dışında, birinci avluda', 'Revan Köşkü\'nün önünde'], 'Biat ve bayramlaşma törenleri için taht Bâbüssaâde önüne kurulur, devlet erkânı sırayla el öper veya yer öperdi.'),
  ('Padişah divan toplantılarına katılmadığı dönemlerde, görüşülenleri gizlice dinleyebilmesi için divan salonuna bitişik hangi yapıda kafesli bir pencere bulunurdu?', 'Adalet Kulesi', ['Bağdat Köşkü', 'Hırka-i Saadet Dairesi', 'Mermer Teras ve İftariye Köşkü'], 'Kubbealtı\'na bitişik Adalet Kulesi\'nde kafesli bir pencere vardı. Padişah buradan divanı izleyebilir, bu durum divan üyelerine denetim hissi verirdi.'),
  ('Topkapı\'daki Revan Köşkü hangi olayın anısına, hangi padişah tarafından yaptırılmıştır?', '1635 Revan seferi, IV. Murad', ['1517 Mısır seferi, Yavuz Sultan Selim', '1453 İstanbul\'un fethi, Fatih Sultan Mehmed', '1534 Irakeyn seferi, Kanuni Sultan Süleyman'], 'Revan Köşkü, IV. Murad\'ın 1635\'te Erivan\'ı (Revan) alması anısına yaptırılmıştır. Hemen ardından Bağdat Köşkü de eklenmiştir.'),
  ('Topkapı Sarayı\'nda padişahın yemeklerinin ve saray mensuplarının yiyeceklerinin hazırlandığı mutfak teşkilatına genel olarak ne ad verilirdi?', 'Matbah-ı Âmire', ['Darüzziyafe', 'Kilâr-ı Âmire', 'İmaret-i Hümâyûn'], 'Saray mutfağına Matbah-ı Âmire denirdi. Kilâr-ı Âmire ise erzakın depolandığı kileri anlatır.'),
  ('Topkapı Sarayı\'nda Enderun Kiler Koğuşu\'ndan yetişen görevlilerin temel hizmet alanı neydi?', 'Padişahın yiyecek, içecek, şerbet ve macunlarının hazırlanması ve sunulması', ['Padişahın silahlarını, kılıcını ve zırhlarını taşıyıp muhafaza etmek ve savaşta yanında bulunmak', 'Padişahın atlarının ve av kuşlarının bakımı', 'Devlet hazinesinin muhafazası ve sayımı'], 'Kiler Koğuşu padişahın sofra ve içecek işlerine bakar; silah işleri silahdarlara, hazine işleri Hazine Koğuşu\'na aitti.'),
  ('Bir ziyaretçi, Topkapı Sarayı\'nda kutsal emanetlerin saklandığı ve gece gündüz Kur\'an okunan bölümü görmek istiyor. Hangi daireye gitmelidir?', 'Hırka-i Saadet Dairesi', ['Kızlarağası Dairesi ve Valide Dairesi', 'Arz Odası', 'Sünnet Odası'], 'Mukaddes emanetler Hırka-i Saadet Dairesi\'nde saklanır ve burada gece gündüz Kur\'an okunurdu.'),
  ('Topkapı\'daki Mermer Teras ve İftariye Kameriyesi gibi yapıların dördüncü avluda bulunması, bu bölümün genel işlevi hakkında ne düşündürür?', 'Padişahın dinlenme ve eğlenmesine ayrılmış, manzaralı bahçe köşkleri bölümü olduğunu', ['Devlet işlerinin görüşüldüğü ve kararların alındığı resmî toplantı salonlarının bulunduğu bölüm olduğunu', 'Askerî birliklerin eğitim gördüğü kışla bölümü olduğunu', 'Saray okulunun öğrenci koğuşlarının bulunduğu yer olduğunu'], 'Dördüncü avlu lale bahçeleri, köşkler ve teraslarla padişahın dinlendiği ve manzara seyrettiği özel alan olarak düzenlenmişti.'),
  ('Padişahın çocuğunu dünyaya getirerek haremde yüksek statü kazanan kadının bu konumunu belirten unvan hangisidir?', 'Haseki', ['Hazinedarbaşı', 'Kalfa', 'Gözde'], 'Padişahın çocuğuna ilk hamile kalan veya en yüksek sıradaki eşe haseki denirdi. Gözde ise padişahın dikkatini çeken, henüz çocuğu olmayan cariyeydi.'),
  ('Haremdeki bir cariye padişahın dikkatini çekmiş ancak henüz çocuğu yoktur. Bu cariyenin konumunu belirten unvan hangisidir?', 'Gözde', ['Haseki', 'Valide', 'Kadınefendi'], 'Padişahın ilgisine mazhar olan cariyeye "gözde", ilgisinin sürdüğü ve belirgin hâle geldiği kişiye "ikbal" denirdi.'),
  ('Haremin işleyişinde "kalfalar" ve "ustalar" hangi görevi yürütürdü?', 'Haremdeki cariyelerin eğitimine ve günlük düzenine nezaret etmek', ['Harem kapısında güvenlik nöbeti tutmak ve ziyaretçileri denetlemek', 'Padişahın özel divan kayıtlarını tutmak', 'Şehzadelere medrese dersleri vermek'], 'Harem cariyeleri kıdem sırasına göre kalfa ve ustalara bağlanır, onlar eğitim ve disiplin işlerini yürütürdü.'),
  ('Harem dairesinde güvenlik ve düzenin sağlanmasından sorumlu, çoğunlukla Afrika kökenli hadım edilmiş görevlilere genel olarak ne denirdi?', 'Harem ağaları (siyah hadımağaları)', ['Bostancılar ve Baltacılar (saray bahçıvanları)', 'Silahdarlar', 'Çuhadarlar'], 'Haremin iç düzeni ve kapısı hadım edilmiş harem ağalarına emanetti; bunların başı Darüssaâde Ağası\'ydı.'),
  ('Haremin padişahtan sonraki en yetkili kadını valide sultanın saray yaşamında etkili olmasının temel dayanağı neydi?', 'Padişahın annesi olarak hanedan üzerinde saygınlığa ve harem idaresine sahip olması', ['Divan-ı Hümayun\'un daimi üyesi olarak oy kullanması ve vezirleri doğrudan atayabilmesi', 'Ordunun başkomutanlığını doğrudan üstlenmesi', 'Şer\'i mahkemelere başkanlık etmesi'], 'Valide sultan padişahın annesi olarak haremi yönetir, bütçe ve vakıf imkânlarıyla siyasette de dolaylı rol oynardı.'),
  ('Fatih Kanunnamesi\'ndeki hükme göre tahta çıkan padişahın kardeşlerini öldürtmesinin gerekçesi ne olarak gösterilmiştir?', 'Devletin birliğini koruma ve fitneyi önleme', ['Hazineye mali tasarruf sağlama', 'Halifelik makamını kazanma', 'Yeniçeri ocağının isteğini yerine getirme'], 'Kardeş katli, nizam-ı âlem için taht mücadelesinin devleti bölmesini önleme gerekçesine dayanıyordu.'),
  ('Genç bir şehzade, yönetim tecrübesi kazanması için babasının emriyle bir kente gönderiliyor. Bu uygulamanın adı nedir?', 'Şehzade sancağı', ['Kafes', 'Sancak divanı ve eyalet yönetimi', 'Dârüsselâm'], 'Şehzadeler babalarının sağlığında sancaklara gönderilir, böylece idarecilik deneyimi kazanırdı. Bu uygulama 17. yüzyılda terk edilmiştir.'),
  ('Kafes uygulamasının devlet yönetimi açısından ortaya çıkardığı belirgin dezavantaj hangisidir?', 'Şehzadelerin yönetim ve ordu deneyimi kazanamadan tahta çıkması', ['Şehzade sayısının hızla azalması ve hanedanın soyunun tükenmeye yüz tutması', 'Vezirlerin yetkilerinin sınırlanması', 'Orduda sipahi sayısının artması'], 'Şehzadeler sarayda dış dünyadan yalıtılmış yetiştiğinden tahta çıktıklarında idare ve savaş tecrübesinden yoksun kalıyordu.'),
  ('Yeni tahta çıkan bir padişah, cülus sonrasında Eyüp Sultan Camii\'nde bir törene katılacaktır. Bu tören hangisidir?', 'Kılıç kuşanma', ['Taç giyme töreni', 'Mühür teslimi', 'Sancak çekme'], 'Yeni padişah Eyüp Sultan\'da Mevlevi şeyhi veya nakibüleşraf tarafından Hz. Osman\'ın kılıcı olarak anılan kılıcı kuşanırdı; bu bir tahta çıkış töreniydi.'),
  ('Padişah sefere çıkıyor; silahlarını ve kılıcını yanında taşıyacak Enderun ağası kimdir?', 'Silahdar Ağa', ['Kızlarağası', 'Mehterhane Ağası', 'Kapıcıbaşı'], 'Silahdar Ağa, padişahın silahlarını taşıyan ve yakınında bulunan Enderun ağasıdır; sonradan önemli devlet adamları arasına girmiştir.'),
  ('Dolmabahçe Sarayı\'nın mimarlığını hangi ailenin üyeleri üstlenmiştir?', 'Garabet ve Nikoğos Balyan', ['Sinan ve Davut Ağa', 'Vedat Tek ve Mimar Kemaleddin Bey', 'Fossati kardeşler'], 'Dolmabahçe Sarayı Sultan Abdülmecid için Ermeni asıllı Osmanlı mimar ailesi Balyanlar\'dan Garabet Balyan ve oğlu Nikoğos tarafından yapıldı.'),
  ('Dolmabahçe Sarayı\'nın Muayede Salonu\'nu süsleyen ve yaklaşık dört buçuk ton ağırlığındaki büyük kristal avize hangi devletin hediyesidir?', 'İngiltere', ['Fransa İmparatorluğu', 'Rusya', 'Avusturya'], 'Muayede Salonu\'ndaki ünlü avize İngiltere Kraliçesi Victoria tarafından Osmanlı padişahına hediye edilmiştir.'),
  ('Sultan Abdülaziz döneminde Boğaz\'ın Anadolu yakasında yaptırılan ve 1869\'da Fransa İmparatoriçesi Eugénie\'yi konuk eden saray hangisidir?', 'Beylerbeyi Sarayı', ['Maslak Kasrı ve Hünkâr Köşkü', 'Çırağan Sarayı', 'Ihlamur Kasrı'], 'Beylerbeyi Sarayı Abdülaziz döneminde yapılmış, yabancı devlet konukları için kullanılan bir saraydır.'),
  ('İstanbul\'un fethinden sonra Fatih\'in ilk yaptırdığı saray ve ardından Topkapı Sarayı yapılınca ölen padişahların haremlerinin gönderildiği yer neresidir?', 'Eski Saray', ['Edirne Sarayı', 'Yıldız Sarayı ve Şale Köşkü', 'Kâğıthane Sarayı'], 'Fatih önce Beyazıt çevresinde Eski Saray\'ı yaptırmış, sonra Topkapı\'ya geçmiştir. Eski Saray daha sonra emekli ve hanedanın bazı kadınlarına ayrılmıştır.'),
  ('17. yüzyılda IV. Mehmed\'in İstanbul\'dan çok Edirne\'de zaman geçirmesinin temel nedeni neydi?', 'Avcılığa düşkünlüğü ve İstanbul\'daki siyasi baskılardan uzak kalma isteği', ['Başkenti resmen Edirne\'ye taşıyarak devlet işlerini oradan yürütmek istemesi', 'Rumeli\'deki seferleri bizzat yönetmek', 'Safevilerle sınır tahkimi yapmak'], 'IV. Mehmed\'e "Avcı" denmesinin nedeni av tutkusuydu. Edirne\'de uzun süre kalarak saray ve İstanbul\'daki çekişmelerden uzak durmayı da tercih etmiştir.'),
  ('Kuruluşundan Vaka-i Hayriye\'ye kadar Yeniçeri Ocağı\'nı oluşturan birliklere genel olarak ne ad verilirdi?', 'Orta', ['Alay', 'Tabur', 'Bölükbaşı'], 'Yeniçeri Ocağı ortalardan oluşurdu; 16. yüzyılda toplam sayı 196 civarındaydı. Her orta bir çorbacı tarafından yönetilirdi.'),
  ('Yeniçeri ortalarının komutanına "çorbacı", alt kademelere "aşçıbaşı" ve "karakullukçu" gibi adlar verilmesi neyi yansıtır?', 'Askerlerin padişahın sofrasından beslenen kulları sayılması anlayışını', ['Yeniçerilerin ticaretle uğraşıp aşçılık yaparak geçimlerini sağlamaları ve loncaya bağlı olmaları', 'Sarayın mutfağının orduya devredilmesini', 'Yemek tarifleri yazılmasının zorunluluğunu'], 'Yeniçeri rütbelerinin mutfak terimleriyle adlandırılması, ocağın padişaha bağlı ve sofrasından geçinen kul statüsünü simgeliyordu.'),
  ('Yeniçerilerin isyan ettiklerini göstermek için meydanda yaptıkları ve "kazan kaldırmak" deyimine kaynaklık eden eylem nedir?', 'Yemek kazanlarını devirmek', ['Kışla kapılarını kapatıp nöbeti terk etmek', 'Topları ateşlemek', 'Sancakları indirmek'], 'Yeniçeri için kazan hem birlik hem onur simgesiydi. Kazanın devrilmesi, padişahın verdiği yemeği ve düzeni reddetme anlamına gelir, isyanın işareti sayılırdı.'),
  ('Yeniçeri Ocağı hangi tarikatla manevi bağ kurmuş, törenlerinde Hacı Bektaş-ı Veli\'ye dua edilmiştir?', 'Bektaşilik', ['Mevlevilik', 'Nakşibendilik', 'Halvetilik'], 'Yeniçeri Ocağı Bektaşi tarikatıyla ilişkilendirilmiştir; ocağın pîri Hacı Bektaş-ı Veli sayılır, Bektaşi babaları ortalarda dua eder ve törenlere katılırdı.'),
  ('Yeniçerilerin başlığı olan börkün ön kısmındaki "kaşıklık" ne amaçla kullanılırdı?', 'Kaşığı takmak için', ['Rütbeyi göstermek için', 'Hançeri saklamak için', 'Sancağı bağlamak için'], 'Yeniçeri börkünün ön kısmındaki kaşıklığa kaşık takılırdı; kaşık ocağın ortak sofrası ve kul kimliğiyle ilişkiliydi.'),
  ('Klasik dönemde yeniçeriler için hangi iki yasak uygulanırdı?', 'Evlenmek ve ticaret yapmak', ['Din değiştirmek ve bayram yapmak', 'Silah taşımak ve ata binmek', 'Yazı yazmak ve okumak'], 'Klasik düzende yeniçeriler kışlada yaşar, evlenemez ve ticaretle uğraşamazdı. Bu yasaklar 16. yüzyıldan itibaren gevşemiş, ocak disiplini zayıflamıştır.'),
  ('Yeniçeri Ocağı\'nın tarihinde kışla ve toplanma merkezi olarak öne çıkan, 1826\'da topa tutulan yeniçeri kışlasının bulunduğu meydan hangisidir?', 'Et Meydanı', ['Atmeydanı', 'Okmeydanı', 'Sultanahmet Meydanı'], 'Yeniçerilerin Et Meydanı\'ndaki kışlası 1826\'da topa tutulmuş, isyan burada bastırılmıştır.'),
  ('Tımar sistemi hangi yıl ve hangi padişah döneminde kaldırılmıştır?', '1831, II. Mahmud', ['1839, Abdülmecid', '1808, IV. Mustafa', '1856, Abdülmecid'], 'Yeni ordu kurulunca tımarlı sipahiye ihtiyaç kalmamış, tımar sistemi 1831\'de II. Mahmud döneminde kaldırılmıştır.'),
  ('17. yüzyılda Osmanlı donanması, kürekli kadırgaların yanında topçu gücünü artırmak için hangi tür yelkenli savaş gemilerini kullanmaya başlamıştır?', 'Kalyon', ['Kadırga', 'Kayık', 'Sandal'], 'Kalyonlar çok toplu yelkenli savaş gemileriydi ve Girit Seferi gibi dönemlerde donanma gücünü artırdı.'),
  ('Osmanlı kadırgalarında kürek çeken denizcilerin büyük bölümü hangi gruptan sağlanırdı?', 'Esirler ve kürek cezasına çarptırılan mahkûmlar', ['Gönüllü olarak başvuran Anadolu köylüleri ve Rumeli esnafı', 'Devşirme yeniçeriler', 'Enderun mensupları'], 'Ağır kürek işi için ücretli gönüllü yerine esirler ve mahkûmlar kullanılırdı; bu yüzden kadırga işgücü sorunu sürekli yaşanırdı.'),
  ('Mehter takımında yer alan ve çok büyük boy davul özelliği taşıyan çalgıya ne ad verilir?', 'Kös', ['Zil', 'Boru', 'Zurna'], 'Kös, mehter takımının büyük vurma çalgısıydı; sesiyle uzaktan da duyulur ve askerlere moral verirdi.'),
  ('Mehterhane hangi olayla birlikte kaldırılmıştır?', '1826\'da Yeniçeri Ocağı\'nın kaldırılması', ['1789\'da III. Selim\'in tahta çıkması ve Nizam-ı Cedid\'in kurulması', '1839\'da Tanzimat\'ın ilanı', '1908\'de II. Meşrutiyet\'in ilanı'], 'Mehterhane yeniçeri ocağıyla bağlantılı sayıldığı için 1826\'da kapatıldı; yerine Batı tarzı bando kuruldu.'),
  ('Padişah sefere bizzat çıktığında ordunun ve devletin simgesi sayılan, kutsal emanetlerden alınan bayrağın adı nedir?', 'Sancak-ı Şerif (kutsal bayrak)', ['Alem-i Hümâyûn', 'Tuğ (at kuyruğu sancağı, makam göstergesi)', 'Çelenk'], 'Padişah sefere çıkınca Sancak-ı Şerif ordunun başında taşınırdı; bu, seferin dinî meşruiyetini ve birliğini simgelerdi.'),
  ('Osmanlı yönetici sınıfı seyfiye (askerler) ve ilmiye (bilginler, kadılar) ile birlikte hangi grup altında incelenir?', 'Kalemiye (divan kâtipleri)', ['Mülkiye (esnaf ve zanaatkârlar)', 'Ticariye (tüccar)', 'Ziraiye (çiftçi)'], 'Yönetici sınıf seyfiye, ilmiye ve kalemiye olarak üç gruba ayrılırdı; kalemiye yazı ve maliye işlerini yürüten kâtiplerden oluşurdu.'),
  ('Osmanlı medreselerinde öğrenim gören öğrencilere genel olarak ne ad verilirdi?', 'Danişmend', ['Müderris', 'Kazasker Efendi', 'Mülâzım'], 'Danişmend, medrese öğrencisidir; Anadolu\'da halk dilinde "softa" da denirdi. Müderris ise ders veren hocadır.'),
  ('Osmanlı\'da İstanbul kadısının diğer şehir kadılarından farklı olarak önemli yetkileri bulunması en iyi neyle açıklanır?', 'Başkentin yargı işlerinin yanında belediye hizmetleri, narh ve piyasa denetimini de yürütmesiyle', ['Divan-ı Hümayun\'a başkanlık edip padişah yerine devlet kararı alma ve orduyu yönetme yetkisine sahip olmasıyla', 'Ordunun komutanı olmasıyla', 'Yalnızca Fatih Külliyesi\'ne bakmasıyla'], 'İstanbul Kadısı, başkentin yargı işlerine bakmanın yanı sıra çarşı ve esnaf denetimi, narh gibi görevlerle belediye yetkilisi gibi çalışırdı.'),
  ('Osmanlı\'da şeyhülislam, resmî olarak aynı zamanda hangi şehrin müftüsü sayılırdı?', 'İstanbul', ['Kastamonu', 'Bursa', 'Konya'], 'Şeyhülislam, İstanbul müftüsü unvanını taşır ve tüm müftülerin başı sayılırdı.'),
  ('Bir kadı mahkemesinde ölen kişinin terekesi şer\'î paylara göre dağıtılacaktır. Bu hesabı hangi görevli yapar?', 'Kassam', ['Muhzır', 'Katip', 'Mübaşir'], 'Kassam, kadı mahkemesinde terekeyi (miras) hukuki payına göre bölüştüren görevlidir.'),
  ('Bir kadı mahkemesinde davalı ve tanıkların mahkemeye getirilmesinden hangi görevli sorumludur?', 'Muhzır', ['Kadı Vekili', 'Naib', 'Müftü'], 'Muhzır, kadı huzuruna davalı ve tanıkların getirilmesini sağlar; böylece mahkemenin işleyişini düzenlerdi.'),
  ('Bir dava sonunda kadının hükmünü yazılı olarak içeren ve davacıya verilen belge hangisidir?', 'İlâm', ['Fetva', 'Berat', 'Ferman'], 'İlâm kadının kararını yazılı olarak içeren mahkeme belgesidir; fetva ise bir hukuki görüş, berat bir görev belgesidir.'),
  ('Şer\'iyye sicilleri tarihçiler için neden değerli bir kaynaktır?', 'Halkın alım satım, miras, evlilik ve vakıf gibi gündelik işlemleri kayıtlı olduğundan', ['Yalnızca padişah fermanlarını, sefer tutanaklarını ve elçi kabul törenlerini içerdiği için', 'Savaş planlarını ayrıntılı verdiği için', 'Diplomatik antlaşma metinleri bulunduğu için'], 'Şer\'iyye sicilleri kadı mahkemelerinde halkın dava ve işlemlerini kaydettiği için, sıradan insanların gündelik hayatını yansıtan temel kaynaklardır.'),
  ('Osmanlı\'da fermanlar ve resmî divan yazışmalarında kullanılan, 15. yüzyıl ortalarında Fatih döneminde şekillenen yazı türü hangisidir?', 'Divânî', ['Muhakkak', 'Nesih', 'Rik\'a'], 'Divânî yazı, resmî yazışmalarda ve fermanlarda kullanılan Osmanlı\'ya özgü bir yazı türüdür; yazımı zor olduğundan sahtecilik de kolay değildi.'),
  ('Padişah, sadrazamın arzı üzerine kendi eliyle karar yazarsa ortaya çıkan belge hangisidir?', 'Hatt-ı hümâyûn', ['Tezkere-i Hümâyûn', 'Berat', 'Fetva'], 'Hatt-ı hümâyûn padişahın kendi el yazısıyla sadrazam arzına yazdığı karar notudur ve en yüksek onay anlamına gelir.'),
  ('Divan-ı Hümayun\'da alınan kararların kaydedildiği ve Osmanlı arşivinin en önemli defter serilerinden biri sayılan defterlere ne ad verilir?', 'Mühimme defterleri', ['Tereke defterleri', 'Ruznamçe defterleri', 'Vakfiye defterleri'], 'Mühimme defterleri merkezî yönetimin eyaletlere gönderdiği hükümlerin kayıtlarını içerir; devlet işlerinin işleyişini gösterir.'),
  ('Bir kişi, mal varlığının gelirini köprü ve çeşme gibi toplumun yararlanacağı hizmetlere ayırıyor. Bu vakıf türü nedir?', 'Hayrî vakıf', ['Ehlî vakıf', 'Zürrî vakıf', 'Mülhak vakıf'], 'Hayrî vakıf doğrudan kamu yararına olan hizmetlere gelir ayırır. Ehlî veya zürrî vakıfta gelir vakfedenin ailesine ve soyuna aittir.'),
  ('Vakfedenin soyundan gelenlerin geçimini güvence altına alan ehlî (evlâdiyelik) vakıfların yaygınlaşması hangi sonucu doğurmuştur?', 'Servetin müsadereden korunarak aile içinde sürekli kılınması', ['Gelirlerin tamamen devlete aktarılıp hayır hizmetlerinin ortadan kalkmasını', 'Dükkânların esnafa dağıtılması', 'Medreselerin sayısının azalması'], 'Ehlî vakıflar mülkü müsadereden korur ve gelirini aileye bırakırdı; bu da hayrî amacı ikinci plana itebiliyordu.'),
  ('Vakıf yönetiminde, vakfın gelirlerini toplayan ve şartlara uygun harcayan görevliye ne ad verilir?', 'Mütevelli', ['Mültezim', 'Ruznamçeci Kâtip', 'Muhtesib'], 'Mütevelli, vakıf şartlarına göre geliri toplar ve harcar. Vakıf yöneticisini denetleyen ise nazırdır.'),
  ('Osmanlı\'da vakıfların merkezî idaresi için II. Mahmud döneminde hangi kurum kurulmuştur?', 'Evkâf-ı Hümâyûn Nezareti', ['Maarif-i Umumiye Nezareti', 'Şûrâ-yı Devlet', 'Meclis-i Vâlâ'], 'Vakıfların devlet denetiminde toplanması ve gelirlerinin düzenlenmesi için 1826\'da Evkâf-ı Hümâyûn Nezareti kurulmuştur.'),
  ('Osmanlı kentlerinde bir külliyenin etrafında yeni mahallelerin ve çarşıların oluşması neyi gösterir?', 'Vakıf yapılarının kentsel gelişmeyi ve nüfus çekmeyi yönlendirdiğini', ['Külliyelerin yalnızca dinî eğitim için kurulduğunu', 'Vakıfların nüfusu azalttığını', 'Çarşıların devlet tarafından yasaklandığını'], 'Külliyeler çevresine çarşı, han ve konutlar gelişerek yeni mahalleler oluşturur, vakıflar kent planlamasında rol oynardı.'),
  ('Osmanlı\'da yolcuların, tüccarların ve yoksulların barınması için yol üzerinde yapılan, genellikle vakıf gelirleriyle işletilen yapılara genel olarak ne denirdi?', 'Han ve kervansaray', ['Konak ve sarayların selamlığı', 'Hamam', 'Medrese'], 'Han ve kervansaraylar yolculara konaklama ve güvenlik sağlıyor, vakıflar aracılığıyla ticaret yollarının işleyişine katkıda bulunuyordu.'),
  ('Osmanlı padişahının kişisel hazinesi niteliğindeki, Enderun\'da saklanan hazineye ne denirdi?', 'İç Hazine', ['Hazine-i Âmire', 'Darphane', 'Dış Hazine'], 'Padişahın şahsına ait ve Enderun\'da saklanan hazine İç Hazine\'dir; devlet hazinesi ise defterdarın yönettiği Hazine-i Âmire\'dir.'),
  ('Osmanlı\'da "kuruş" adı hangi sözcükten türemiştir?', 'Alman gümüş sikkesi Groschen', ['İtalyan altını dukato', 'Fransız sikkesi franc', 'Rus rublesi'], 'Kuruş adı, Avrupa\'dan yayılan gümüş sikke Groschen\'den türemiştir; 17. yüzyılda yaygınlaşmıştır.'),
  ('1864 Vilayet Nizamnamesi\'nde vilayetin başında hangi görevli bulunurdu?', 'Vali', ['Mutasarrıf', 'Kaymakam', 'Müdür'], 'Vilayetin başında vali, sancağın başında mutasarrıf, kazanın başında kaymakam, nahiyenin başında müdür bulunurdu.'),
  ('Osmanlı\'da kahve hangi bölgeden gelerek İstanbul\'da yaygınlaşmıştır?', 'Yemen', ['Hindistan', 'Brezilya', 'Kuzey Afrika'], 'Kahve, Yemen\'den Mısır ve Suriye üzerinden İstanbul\'a gelmiş, 16. yüzyılın ortalarında İstanbul\'da ilk kahvehaneler açılmıştır.'),
  ('Osmanlı kahvehanelerine "Mekteb-i İrfan" (irfan okulu) denmesinin nedeni nedir?', 'Sohbet, okuma, şiir ve oyunlarla toplumsal bilgi alışverişinin yapıldığı yerler olmaları', ['Burada medreselerdeki resmî derslerin verilmesi ve ilmiye sınıfı mensuplarının icazet sınavı yapması', 'Yalnız devlet memurlarının girebilmesi', 'Padişaha ders veren hocaların burada toplanması'], 'Kahvehaneler halkın sohbet ettiği, haber aldığı, şiir ve hikâye dinlediği sosyal mekânlar olduğundan bu ad verilmiştir.'),
  ('Bir erkek hamamında müşterinin kesesini yapan ve yıkayan çalışana ne denir?', 'Tellak', ['Natır', 'Külhanbeyi', 'Hamamcı çırağı'], 'Tellak erkek hamamlarında kese ve sabunlama yapan görevlidir; kadın hamamlarında bu işi natırlar yapardı.'),
  ('Bir hamamda suyun ısıtıldığı ocak hangi bölümde bulunur?', 'Külhan', ['Sıcaklık', 'Soğukluk', 'Camekân'], 'Külhan, hamamın ocağıdır; hamamın su ve zemin ısıtma sistemi buradan beslenirdi.'),
  ('Osmanlı kadınları için hamamın toplumsal açıdan en önemli işlevi neydi?', 'Kadınların bir araya gelip sosyalleştiği, gelin adayı beğenme ve haberleşme mekânı olması', ['Padişaha danışmanlık yapılması ve devlet işlerinin kadınlar arasında görüşülüp karara bağlanması', 'Kadınlara medrese eğitimi verilmesi', 'Alışveriş yapılması'], 'Hamamlar kadınların ev dışında toplandığı nadir mekânlardandı; gelin adayı seçme, düğün hazırlıkları ve sohbet burada yapılırdı.'),
  ('Osmanlı\'da 19. yüzyıl başlarında devlet görevlileri ve askerler için zorunlu başlık hâline gelen "fes" adını hangi şehirden almıştır?', 'Fas\'ın Fes şehrinden', ['Mısır\'ın Kahire şehrinden', 'Suriye\'nin Halep şehrinden', 'Yemen\'in Sana şehrinden'], 'Fes, adını Fas\'taki Fes şehrinden alır; başlık Osmanlı\'da II. Mahmud döneminde resmî başlık oldu.'),
  ('Osmanlı kadınlarının sokakta giydiği, geleneksel dış giysi hangisidir?', 'Ferace ve yaşmak', ['Kaftan ve kavuk', 'Şalvar ve börk', 'Ceket ve pantolon'], 'Osmanlı kadınları sokakta ferace ve yaşmak taşırdı. Kavuk ve börk erkek başlıklarıdır.'),
  ('Bir Ramazan akşamı iki minare arasına kandillerle yazı yazıldığını görüyorsunuz. Bu geleneğe ne ad verilir?', 'Mahya', ['Tezhip', 'Hüsn-i hat', 'Ebru'], 'Mahya, Ramazan\'da camilerin minareleri arasına asılan kandillerle yazı ve şekiller yapılmasıdır.'),
  ('Osmanlı şehirlerinde Ramazan\'da sahur ve iftar vakitlerini halka duyurmak için hangi uygulama yapılırdı?', 'Top atışı', ['Kandil yakılması', 'Çan çalınması', 'Meşale taşınması'], 'Sahur ve iftar vakitleri top atışıyla duyurulur, Ramazan davulcuları ise mahalle mahalle dolaşıp halkı uyandırırdı.'),
  ('Osmanlı halkının baharın gelişini kutladığı ve Hızır ile İlyas\'ın buluştuğuna inanılan gün hangisidir?', 'Hıdırellez', ['Nevruz', 'Nevruz-ı Sultani', 'Arife'], 'Hıdırellez, baharın başlangıcı sayılan ve Hızır ile İlyas\'ın buluştuğuna inanılan gündür; halk piknik, dilek ve şenliklerle kutlardı.'),
  ('Karagöz oyununda Hacivat\'ın konuşma biçimi ve kişiliği hangi toplumsal tipi yansıtır?', 'Okumuş, ağdalı konuşan kişiyi', ['Halk içinden sade, okumamış tipi', 'Padişahı', 'Yeniçeri ağasını'], 'Hacivat okumuş, eğitimli ve ağdalı konuşan tiptir. Karagöz ise halk adamını temsil eder.'),
  ('Ortaoyunu\'nun iki temel karakteri hangileridir?', 'Pişekâr ve Kavuklu', ['Karagöz ve Hacivat perdesi', 'Meddah ve Nakkal', 'Köçek ve Çengi'], 'Ortaoyunu\'nda Kavuklu halk tipini, Pişekâr ise akıllı ve yönlendirici kişiyi temsil eder; meydanda oynanan seyirlik oyundur.'),
  ('Tek kişinin hikâye anlatıp taklitler yaparak seyirciyi eğlendirdiği geleneksel Osmanlı gösteri sanatı hangisidir?', 'Meddahlık', ['Kuklacılık', 'Cirit', 'Mehter'], 'Meddah, kahvehanelerde ve konaklarda tek başına hikâye anlatan, ses ve taklit yeteneğini kullanan sanatçıdır.'),
  ('Bir Osmanlı evinde erkek misafirler hangi bölümde ağırlanırdı?', 'Selamlık', ['Haremlik', 'Hayat', 'Sofa'], 'Selamlık erkek misafirlerin ağırlandığı bölümdür; haremlik ise ailenin ve kadınların kullandığı kısımdır.'),
  ('Bir Osmanlı evinin üst katında sokağa doğru taşan kafesli bölüme ne denir?', 'Cumba', ['Sofa', 'Şadırvan', 'Ocak'], 'Cumba, ahşap evlerin üst kat çıkmasıdır; kadınların sokağı görmesine fırsat verir, evin iç mekânını genişletirdi.'),
  ('Mimar Sinan\'ın İstanbul\'da yaptığı Şehzade Camii hangi şehzadenin anısına yaptırılmıştır?', 'Kanuni\'nin oğlu Şehzade Mehmed', ['Kanuni\'nin oğlu Şehzade Mustafa', 'Fatih\'in oğlu Şehzade Cem', 'Yavuz\'un oğlu Şehzade Korkut'], 'Şehzade Camii, 1543\'te ölen Kanuni\'nin oğlu Şehzade Mehmed adına yaptırılmıştır ve Sinan\'ın çıraklık dönemi eseri sayılır.'),
  ('Sinan\'ın Rüstem Paşa Camii\'ni özellikle ünlü kılan iç mekân özelliği nedir?', 'İznik çinileriyle kaplı duvarlar', ['Altın yaldızlı kubbe ve minareler', 'Mermer sütunlu galeri', 'Taş oymalı kapı'], 'Rüstem Paşa Camii, duvarlarını kaplayan zengin İznik çinileriyle ünlüdür; Eminönü\'nde küçük ölçekli bir yapıdır.'),
  ('Sultanahmet Camii\'nin mimarı olan ve Sinan\'ın öğrencisi sayılan kişi kimdir?', 'Sedefkâr Mehmed Ağa', ['Mimar Davud Ağa', 'Kasım Ağa', 'Hayreddin'], 'Sultanahmet Camii, I. Ahmed adına 1609-1616 yılları arasında yapılmış, mimarı Sedefkâr Mehmed Ağa\'dır; altı minaresiyle tanınır.'),
  ('İstanbul\'daki Ortaköy Camii hangi mimar ailesinin eseridir?', 'Balyan ailesi', ['Fossati ailesi', 'Vedat Tek ailesi', 'Kemaleddin ailesi'], 'Ortaköy Camii, Balyan ailesinden Nikoğos Balyan tarafından 19. yüzyılın ortasında barok ve neoklasik etkilerle yapılmıştır.'),
  ('Topkapı Sarayı\'nın Bâb-ı Hümâyûn önündeki 1728 tarihli, Lale Devri\'ni yansıtan çeşme hangi padişah adına yapılmıştır?', 'III. Ahmed', ['I. Mahmud', 'III. Mustafa', 'II. Mahmud'], 'III. Ahmed Çeşmesi, Lale Devri\'nin süslemeci üslubunu yansıtan ve kitabesinde tarih manzumesi bulunan meydan çeşmesidir.'),
  ('İznik\'in çini üretimindeki önemini yitirmesinden sonra çini sanatı hangi şehirde öne çıkmıştır?', 'Kütahya', ['Konya', 'Diyarbakır', 'Edirne'], '17. yüzyıldan itibaren İznik gerilemiş, 18. yüzyılda Kütahya çini üretimiyle öne çıkmıştır.'),
  ('Mimar Sinan\'ın Osmanlı saray teşkilatındaki resmî görevi neydi?', 'Hassa Başmimarı (saray baş mimarı)', ['Sadrazam', 'Kaptan-ı derya (donanmanın başkomutanı)', 'Defterdar'], 'Sinan, devşirmelikten yetişip yeniçeri olarak sefere katıldıktan sonra Hassa Mimarlar Ocağı\'nın başına geçti ve uzun yıllar Hassa Başmimarı olarak çalıştı.'),
  ('Mevlevi âyinlerinde ritmi tutmak için kullanılan çift davul niteliğindeki çalgı hangisidir?', 'Kudüm', ['Bendir', 'Darbuka', 'Def'], 'Kudüm, Mevlevi musikisinde ritmi sağlayan çift davuldur; ney ile birlikte ayin müziğinin temel çalgılarındandır.'),
  ('Osmanlı\'da ilk telgraf hattı hangi savaş sırasında kurulmuştur?', 'Kırım Savaşı', ['93 Harbi', 'Balkan Savaşları', 'Trablusgarp Savaşı'], 'Osmanlı\'da ilk telgraf hattı 1855\'te Kırım Savaşı sırasında İstanbul-Edirne-Şumnu arasında kurulmuş, haberleşme hızlanmıştır.'),
  ('İstanbul\'da Fatih döneminde yapımına başlanan ve Kapalıçarşı\'nın çekirdeğini oluşturan yapı hangisidir?', 'İç Bedesten', ['Mısır Çarşısı', 'Büyük Valide Han', 'Sahaflar Çarşısı'], 'İç Bedesten (Cevahir Bedesteni), Fatih döneminde kurulan ve değerli malların saklandığı yapıdır; sonradan etrafında Kapalıçarşı gelişmiştir.'),
  ('Osmanlı\'da kadınların hukuki işlemlerini, mülkiyet ve miras haklarını kadı huzurunda kullanabilmesi neyi gösterir?', 'Kadınların mahkemeye başvurabildiğini ve mal sahibi olabildiğini', ['Kadınların her türlü yönetim görevinde bulunduğunu ve erkeklerle tamamen aynı haklara sahip olduğunu', 'Kadınların oy kullandığını', 'Kadınların askerlik yaptığını'], 'Şer\'iyye sicilleri kadınların mahkemeye başvurup mirasçı ve mülk sahibi olduklarını, vakıf kurabildiklerini göstermektedir.'),
  ('Ahmed Cevdet Paşa\'nın kızı olan ve Osmanlı\'nın ilk kadın romancısı kabul edilen yazar kimdir?', 'Fatma Aliye', ['Halide Edib Adıvar', 'Nigâr Hanım', 'Fatma Zehra'], 'Fatma Aliye Hanım, Ahmed Cevdet Paşa\'nın kızıdır; 19. yüzyıl sonunda romanlar ve yazılarla Osmanlı kadın edebiyatının öncüsü olmuştur.'),
  ('Kanuni\'nin kızı olan ve Üsküdar ile Edirnekapı\'da camileri bulunan, Osmanlı\'da hayır işleriyle tanınan sultan kimdir?', 'Mihrimah Sultan', ['Hürrem Sultan', 'Nurbanu Sultan', 'Kösem Sultan'], 'Mihrimah Sultan, Mimar Sinan\'a Üsküdar ve Edirnekapı\'da iki cami yaptırmış ve vakıfları sayesinde sosyal hizmetlere katkı vermiştir.'),
  ('İslam hukukunda Müslüman olmayan ve devlet himayesinde yaşayan bir kişi hangi statüde sayılır?', 'Zimmî (korunan gayrimüslim)', ['Reaya (vergi ödeyen Müslüman halk)', 'Mevlâ', 'Kul'], 'Zimmî, Müslüman olmayan tebaayı anlatır; zimmîler cizye ödeyerek can ve mal güvencesine kavuşurdu.'),
  ('Kanun-i Osmani\'nin şer\'î hukuka uygun olması koşulunun aranması neyi gösterir?', 'Padişah kanunlarının dinî hukuk çerçevesinde meşrulaştırıldığını', ['Kanunların tamamen kaldırıldığını ve yalnızca şer\'î hukukun uygulandığını', 'Şer\'î hukukun yalnız medreselerde uygulandığını', 'Padişahın tüm kararlarda mutlak yetkili olduğunu'], 'Örfî kanunlar şer\'î hukuka aykırı olmamak zorundaydı; bu çerçeve padişah yetkisini dinî meşruiyet çizgisiyle sınırlıyordu.'),
  ('Padişaha ve vezirlere devlet yönetimi hakkında öğüt veren Osmanlı eserlerine genel olarak ne ad verilir?', 'Nasihatname', ['Sefaretname ve Surname', 'Vakanüvis', 'Seyahatname'], 'Nasihatnameler, yönetimin bozulduğu dönemlerde padişaha ve devlet adamlarına öğüt veren, durum tespiti yapan eserlerdir.'),
  ('1509\'da İstanbul\'da büyük yıkıma yol açan ve halk arasında "Küçük Kıyamet" olarak anılan afet hangisidir?', 'Deprem', ['Büyük yangın', 'Sel', 'Veba'], '1509 depremi, II. Bayezid döneminde İstanbul\'da büyük yıkıma ve can kaybına neden olduğundan "Küçük Kıyamet" olarak anılmıştır.'),
  ('Osmanlı İstanbul\'unda büyük yangınların sık çıkmasının temel nedenleri nelerdi?', 'Ahşap yapıların çokluğu, dar sokaklar ve açık ateşle ısınma ve aydınlanma', ['Kış mevsiminin aşırı sıcak geçmesi ve kuyuların kuruması', 'Geniş caddeler', 'Sürekli yağmur'], 'Ahşap evler, bitişik düzen, dar sokaklar ve açık ateşle ısıtma ve aydınlatma yangının hızla yayılmasına yol açardı.'),
  ('İstanbul\'un büyük kulelerinde (Beyazıt Yangın Kulesi gibi) görevli gözcülerin işi neydi?', 'Şehri izleyip yangını haber vermek', ['Namaz vakitlerini ve bayram günlerini ilan etmek', 'Düşman gemilerini saymak', 'Devlet kasasını korumak'], 'Yangın kuleleri şehri gözetleyerek yangını erken fark edip halka ve tulumbacılara haber vermek için kullanılmıştır.'),
  ('Mevlevi sema töreninde semazenlerin sağ elini yukarı, sol elini aşağı tutmasının anlamı nedir?', 'Ilahi olandan alıp halka vermek', ['Yeryüzünden aldığını göğe sunup yeryüzüne iade etmek', 'Dünyayı terk ettiğini göstermek', 'Padişaha bağlılık yemini etmek'], 'Sağ el gökyüzüne açılarak ilahi feyzi alır, sol el yere dönerek bu feyzi insanlara iletir; sema bu evren düzeninin simgesidir.'),
  ('Mevlevi dervişlerinin başlarına giydikleri, uzun keçeden yapılmış konik başlığa ne ad verilir?', 'Sikke', ['Kavuk', 'Börk', 'Fes'], 'Sikke, Mevlevilerin giydiği keçe başlıktır; mezar taşı olarak da Mevlevi sikkesi şekli görülür.'),
  ('Bektaşilikteki "dört kapı" anlayışında kapıların doğru sıralaması hangisidir?', 'Şeriat, tarikat, marifet, hakikat', ['Tarikat, şeriat, marifet ve hakikat', 'Şeriat, marifet, tarikat, hakikat', 'Hakikat, marifet, tarikat, şeriat'], 'Dört kapı kırk makam öğretisinde kapılar şeriat, tarikat, marifet ve hakikat olarak sıralanır.'),
  ('1826\'da Yeniçeri Ocağı kaldırılınca Bektaşi tekkelerine yönelik uygulama ne olmuştur?', 'Tekkeler kapatılmış ve Bektaşilik yasaklanmıştır', ['Tekkeler devletçe desteklenmiş ve şeyhlerine ayrı vakıf gelirleri bağlanmıştır', 'Tekkelerin gelirleri artırılmıştır', 'Bektaşi şeyhlerine padişah maaşı bağlanmıştır'], 'Bektaşilik, yeniçerilerle özdeşleştirildiği için 1826\'dan sonra yasaklanmış, tekkeler kapatılmış veya başka tarikatlara devredilmiştir.'),
  ('Eyüp Sultan Camii\'nin ve külliyesinin İstanbul\'da yaptırılması hangi padişah dönemine aittir?', 'Fatih', ['Kanuni', 'I. Ahmed', 'III. Ahmed'], 'Eyüp Sultan Camii, İstanbul\'un fethinden kısa süre sonra Fatih tarafından Ebû Eyyûb el-Ensârî\'nin kabri çevresinde yaptırılmıştır.'),
  ('Enderun\'da eğitim gören öğrencilere genel olarak ne ad verilirdi?', 'İç oğlanı', ['Acemi oğlanı', 'Gedikli', 'Müstahfız yamağı'], 'Enderun öğrencileri iç oğlanı olarak adlandırılır ve padişah hizmetinde disiplinli bir eğitimden geçerek devlet kademelerine hazırlanırdı.'),
  ('Padişah ata binerken üzengisini tutan ve törenlerde yakınında bulunan Enderun ağası hangisidir?', 'Rikâbdar', ['Dülbend ağası', 'Kapıcıbaşı', 'Çaşnigirbaşı'], 'Rikâbdar, padişahın üzengisini tutan ve onun yakınında hizmet eden Enderun ağasıdır; ağalıklar içinde itibarlı bir makam sayılırdı.'),
  ('Padişah cuma namazına resmî alayla gidiyor ve halk onu selamlıyor. Bu törene ne ad verilir?', 'Cuma selamlığı', ['Surre alayı ve hac kafilesi', 'Arz günü', 'Kılıç alayı'], 'Cuma selamlığı, padişahın halkla görünür biçimde buluştuğu, güvenlik ve törensel düzenin birlikte yürütüldüğü haftalık törendi.'),
  ('Yeniçeri ulufesinin ödendiği günlerde yapılan ve yabancı elçilerin de ağırlandığı gösterişli divan toplantısına ne denirdi?', 'Galebe Divanı', ['Arz Divanı', 'Ayak Divanı', 'Kubbealtı Divanı'], 'Galebe Divanı, ulufe ödemelerinin yapıldığı günlerde düzenlenen tören nitelikli divandı; devletin gücü elçilere de sergilenirdi.'),
  ('Osmanlı padişahının, Yavuz Sultan Selim\'den sonra kullanmaya başladığı ve Mekke ile Medine\'nin korunmasını simgeleyen unvan hangisidir?', 'Hâdimü\'l-Haremeyn', ['Halife-i Rûy-i Zemîn', 'Zıllullah', 'Şehinşah'], 'Hâdimü\'l-Haremeyn, Mekke ve Medine\'nin hizmetkârı anlamına gelir; Mısır\'ın fethinden sonra padişahların itibarını güçlendirmiştir.'),
  ('Topkapı Sarayı hangi yıl müzeye dönüştürülmüştür?', '1924 (Cumhuriyet\'in ilk yılları)', ['1908 (II. Meşrutiyet\'in ilan edildiği yıl)', '1938', '1950'], 'Topkapı Sarayı, Cumhuriyet\'in ilk yıllarında 1924\'te müze olarak halka açılmıştır.'),
  ('Dolmabahçe Sarayı\'nın Batı üsluplarıyla yapılmış olması Osmanlı sarayı açısından neyi gösterir?', 'Hanedanın gösterişinde ve yaşam biçiminde Avrupa etkisinin arttığını', ['Hanedanın Doğu geleneklerini güçlendirip Avrupa etkisinden uzaklaştığını', 'Sarayın askerî amaçla kullanıldığını', 'Başkentin Ankara\'ya taşındığını'], 'Dolmabahçe\'nin barok, rokoko ve neoklasik öğeleri Osmanlı hanedanının Avrupa saraylarıyla yarışma isteğini ve yaşam tarzı değişimini gösterir.'),
  ('Osmanlı sarayında III. Ahmed döneminde yapılan, Lale Devri\'nin eğlence mekânı olarak bilinen mesire ve saray alanı neresidir?', 'Sadabad', ['Kâğıthane Köşkü', 'Yıldız', 'Ihlamur'], 'Sadabad, Kâğıthane\'de III. Ahmed ve Nevşehirli Damat İbrahim Paşa döneminde yaptırılan saray ve mesire alanıdır.'),
  ('Matbaa yaygınlaşmadan önce bir kitabın nüshasını elle çıkaran kişi kimdir?', 'Müstensih', ['Müderris', 'Muhzır', 'Mütevelli'], 'Matbaa yaygınlaşmadan önce kitaplar müstensihler tarafından elle çoğaltılır; hattatlık ve istinsah önemli bir meslekti.'),
  ('Bir medrese öğrencisi Kur\'an okurken kitabı X biçimli katlanır ahşap sehpaya koyuyor. Bu sehpanın adı nedir?', 'Rahle', ['Sedir', 'Mihrap', 'Kürsü'], 'Rahle, ahşap, katlanır kitap sehpasıdır; öğrenciler Kur\'an veya kitap okurken kitabı üzerine koyardı.'),
  ('Osmanlı\'da Tanzimat sonrası açılan yeni okulların eskiden olduğu gibi yalnız dinî eğitim yapmaması neyi gösterir?', 'Fen ve pozitif bilimlerin önem kazanması ve memur ile subay ihtiyacının karşılanmaya çalışılması', ['Eğitimin yabancı misyonerlere devredilip ders programlarının yalnızca dinî ilimlere indirilmesi gerektiği', 'Medreselerin tamamen kapatıldığını', 'Yalnızca azınlık okullarının açıldığını'], 'Yeni okullar fen, dil, hukuk ve mühendislik gibi alanlarda memur ve subay yetiştirmeyi amaçlıyordu; medreselerle yan yana varlığını sürdürdü.'),
  ('Doğum yapan bir kadını ziyarete gelen misafirlere kırmızı bir şerbet ikram ediliyor. Bu şerbet nedir?', 'Lohusa şerbeti', ['Gül şerbeti', 'Demirhindi', 'Hoşaf'], 'Lohusa şerbeti, şeker, tarçın ve karanfille hazırlanan kırmızı şerbettir; doğum sonrası ziyaretlerde ikram edilen önemli bir gelenekti.'),
  ('Osmanlı\'da 1 okka 400 dirhem sayıldığına göre 3 okka kaç dirhemdir?', '1200', ['1000', '800', '1600 dirhem'], '1 okka 400 dirhem olduğundan 3 x 400 = 1200 dirhem eder.'),
  ('Osmanlı İstanbul\'unda şerbet ve içecekleri soğutmak için kullanılan kar nereden getirilirdi?', 'Uludağ (Bursa)', ['Erciyes Dağı (Kayseri)', 'Kaz Dağları', 'Palandöken'], 'Kar Uludağ\'dan toplanıp İstanbul\'a getirilir ve kar kuyularında saklanırdı; şerbet ve dondurma gibi ürünlerin soğutulmasında kullanılırdı.'),
  ('Osmanlı\'da Ramazan ayının on beşinci günü Topkapı Sarayı\'ndan yeniçerilere dağıtılan tatlıya ne ad verilirdi?', 'Baklava', ['Lokum ve şeker', 'Aşure', 'Güllaç'], 'Baklava Alayı, padişahın yeniçerilere baklava ikram ettiği törendir; padişah ve ordu arasındaki bağı simgelerdi.'),
  ('Edirne\'de her yıl düzenlenen ve Osmanlı güreş geleneğini sürdüren tarihî müsabaka hangisidir?', 'Kırkpınar yağlı güreşleri (Edirne)', ['Cirit müsabakaları (atlı süvari sporu)', 'Okmeydanı yarışı', 'Mevlevi ayini'], 'Kırkpınar, Edirne\'nin Sarayiçi bölgesinde yapılan yağlı güreşlerle özdeşleşen, yüzyıllara dayanan bir gelenektir.'),
  ('Osmanlı sipahilerinin süvari becerisini geliştirmek için yaptığı, atlı iki takım arasında oynanan eski spor hangisidir?', 'Cirit', ['Polo', 'Okçuluk', 'Gülle atma'], 'Cirit, atlı süvarilerin birbirlerine kamış çubuk atmaya çalıştığı bir oyundur; hem eğlence hem de askerî eğitim işlevi görürdü.'),
  ('Osmanlı\'da Muhibbî mahlasıyla şiir yazan padişah kimdir?', 'Kanuni Sultan Süleyman', ['Yavuz Sultan Selim', 'II. Selim', 'III. Mehmed'], 'Kanuni, Muhibbî mahlasıyla Türkçe ve Farsça şiirler yazmış, sanatçıları himaye etmiştir.'),
  ('Osmanlı\'da "Bâb-ı Âli" deyimi hangi anlamda kullanılmıştır?', 'Sadrazamın makamı ve merkezî hükümet', ['Padişahın özel odası ve harem dairesi', 'Saray mutfağı', 'Yeniçeri kışlası'], 'Bâb-ı Âli (Yüksek Kapı), 17. yüzyıldan itibaren sadrazamın dairesini ve hükümeti anlatan, devlet yönetiminin merkezini simgeleyen terim olmuştur.'),
  ('Padişah bir veziri ödüllendirmek için ona kaftan giydiriyor. Bu kaftana ne ad verilir?', 'Hil\'at', ['Berat', 'Nişan', 'Ferman'], 'Hil\'at, padişahın bir kişiye hediye ettiği değerli giysidir; atamalarda ve elçi kabullerinde onur belirtisi sayılırdı.'),
  ('Padişah, eserini sunan bir şaire ödül veriyor. Bu ödüle ne denir?', 'Caize', ['Ulufe', 'Bedel', 'Cizye'], 'Caize, padişahın şair veya bilgine sunduğu armağan ya da ödüldü; sanatçıların saray himayesindeki konumunu da gösterir.'),
  ('Osmanlı Dönemi\'nde İstanbul idari açıdan dört kadılığa ayrılmıştı. Bunlar hangileridir?', 'İstanbul, Galata, Eyüp, Üsküdar', ['İstanbul, Edirne, Bursa, Üsküdar', 'Galata, Pera, Beşiktaş, Kadıköy', 'İstanbul, Bakırköy, Eyüp, Beykoz'], 'İstanbul kadılığı, Galata, Eyüp ve Üsküdar kadılıkları şeklinde dörde ayrılmıştı; her birinin ayrı yargı ve belediye görevleri vardı.'),
  ('İstanbul\'da geleneksel olarak Rum nüfusun yoğun yaşadığı ve Patrikhane\'ye ev sahipliği yapan semt hangisidir?', 'Fener', ['Balat', 'Kumkapı', 'Eyüp'], 'Fener, Haliç kıyısındaki Rum Ortodoks cemaatinin merkezi olan ve Patrikhane\'yi barındıran semttir.'),
  ('Osmanlı İstanbul\'unda geleneksel olarak Ermeni cemaatinin yoğun yaşadığı Marmara kıyısındaki semt hangisidir?', 'Kumkapı', ['Fener', 'Balat', 'Üsküdar'], 'Kumkapı, Ermeni Patrikhanesi\'nin yer aldığı ve yoğun Ermeni nüfuslu semttir.'),
  ('Her yıl Surre Alayı\'nın İstanbul\'dan çıkıp Anadolu yakasına geçerek hac yoluna koyulduğu yer neresidir?', 'Üsküdar', ['Beşiktaş', 'Eyüp', 'Tophane'], 'Üsküdar, Anadolu yakasında hac yolunun başlangıcı sayılır; surre alayı buradan Şam ve Hicaz\'a doğru yola çıkardı.'),
  ('Osmanlı\'da bir kervansarayın en önemli işlevi neydi?', 'Yolculara konaklama, güvenlik ve ihtiyaçlarını sağlamak', ['Askerleri eğitmek ve cephaneyi depolayıp savaş zamanı orduya dağıtmak', 'Vergi toplamak', 'Mahkemeleri toplamak'], 'Kervansaraylar, ticaret ve hac yollarında yolculara barınak, yem, güvenlik ve hizmet sağlayan vakıf yapılarıydı.'),
  ('Osmanlı kervan yolları üzerindeki hanlar neden yaklaşık bir günlük yürüyüş mesafesiyle yapılırdı?', 'Kervanların gün sonunda güvenli biçimde konaklayabilmesi için', ['Hanların vergi toplayabilmesi ve her gün yeni bir kasabaya ulaşılabilmesi için', 'Devletin sınırı korumak istemesi için', 'Yolcuların yürümeyi sevmemesi için'], 'Kervanlar günde belirli mesafe kat ettiğinden hanlar bir günlük yol aralıklarla yapılarak geceleme güvenliği sağlanırdı.'),
  ('Osmanlı\'da deniz yoluyla İstanbul içi ulaşımda kullanılan ve Boğaz\'ın iki yakasında hizmet veren geleneksel ahşap kayık türü hangisidir?', 'Kayık (Bostancı kayığı gibi)', ['Kadırga (kürekli savaş gemisi)', 'Kalyon', 'Mavna'], 'İstanbul\'da şehir içi ulaşım büyük ölçüde kayıklarla sağlanırdı; sultan kayıkları ise törensel kullanıma ayrılmış gösterişli kayıklardı.'),
  ('19. yüzyılda İstanbul\'da Boğaz yolculuğunu kolaylaştıran ve 1850\'lerde kurulan buharlı gemi şirketi hangisidir?', 'Şirket-i Hayriye', ['Osmanlı Bankası', 'Reji İdaresi', 'Hamidiye Kumpanyası'], 'Şirket-i Hayriye 1851\'de Boğaz\'da şehir hatları vapurculuğunu başlatmış, İstanbul\'un ulaşımında yeni bir dönem açmıştır.'),
  ('Fatih Sultan Mehmed\'in İstanbul\'u fethettikten sonra kullandığı ve kendisini Roma imparatorlarının varisi olarak gören unvan hangisidir?', 'Kayser-i Rûm', ['Hâkan', 'Şehinşah', 'Emîrü\'l-Mü\'minîn'], 'Fatih, "Kayser-i Rûm" unvanıyla Doğu Roma mirasına sahip çıkmış, İstanbul\'u imparatorluk başkenti yapmıştır.'),
  ('Mecelle\'nin dayandığı fıkıh mezhebi hangisidir?', 'Hanefi', ['Şafii', 'Malikî', 'Hanbelî'], 'Osmanlı resmî mezhebi Hanefi\'dir; Mecelle de Hanefi fıkhından seçilen hükümlerle hazırlanmıştır.'),
  ('Evden eve dolaşıp kumaş ve takı satan, aynı zamanda gelin adayı haberini taşıyan kadınlara ne ad verilir?', 'Bohçacı kadınlar (gezgin satıcılar)', ['Natır (kadın hamamında yıkayan görevli)', 'Ebe', 'Çengi'], 'Bohçacı kadınlar, kumaş ve süs eşyasını bohçalarla evlere taşıyan, kadınlar arasında haber ve gelin adayı aktarımında aracılık yapan kadınlardı.'),
  ('Sultanahmet Camii\'nin mimarına "sedefkâr" denilmesinin nedeni nedir?', 'Sedef kakma sanatındaki ustalığı', ['Denizcilik ve gemi yapımındaki ustalığı nedeniyle', 'Mimarlığı Venedik\'te öğrenmesi', 'Hat sanatında çalışması'], 'Mehmed Ağa, sedef kakmacılıktaki başarısıyla "sedefkâr" unvanını almış, sonra mimarbaşı olmuştur.'),
  ('Fatih\'in fetihten sonra İstanbul\'u yeniden canlandırmak için Anadolu ve Balkanlar\'dan nüfusu zorunlu olarak yerleştirmesi uygulamasına ne ad verilir?', 'Sürgün (iskân)', ['Devşirme (kul toplama)', 'Pençik', 'Müsadere'], 'Fatih fetihten sonra İstanbul\'u canlandırmak için sürgün yoluyla Anadolu ve Rumeli\'den Müslüman ve gayrimüslim nüfusu yerleştirmiştir.'),
  ('Müslümanlarca kandil olarak kutlanan Kadir Gecesi hangi hicri ayda yer alır?', 'Ramazan', ['Muharrem', 'Şaban', 'Zilhicce'], 'Kadir Gecesi Ramazan ayındadır; Kur\'an\'ın indirilmeye başlandığı gece olarak kutlanır ve genellikle 27. gece anılır.'),
  ('Osmanlı\'da Muharrem ayının onuncu günü hazırlanan ve çeşitli kuru yemişlerin karıştırıldığı geleneksel tatlı hangisidir?', 'Aşure', ['Zerde', 'Güllaç', 'Revani'], 'Aşure, Muharrem ayında hazırlanıp komşulara dağıtılan çok malzemeli bir tatlıdır; paylaşma geleneğiyle özdeşleşmiştir.'),
  ('Osmanlı\'da Berat Kandili hangi hicri ayda kutlanırdı?', 'Şaban', ['Receb', 'Rebiülevvel', 'Şevval'], 'Berat Kandili Şaban ayının on beşinci gecesi kutlanır, kul hakları ve af temalı dua gecesi olarak değerlendirilirdi.'),
  ('Osmanlı\'da haftalık resmî tatil günü hangi gündü?', 'Cuma', ['Cumartesi', 'Pazar', 'Pazartesi'], 'Osmanlı\'da cuma günü hafta tatiliydi; Cumhuriyet döneminde hafta tatili günleri değiştirilmiştir.'),
  ('Bir vakıf mütevellisi, vakfiyede yazılı "her gün yoksullara çorba dağıtılması" şartını kendi kararıyla kaldırmak istemektedir. Osmanlı vakıf hukukuna göre bu istek nasıl karşılanır?', 'Kabul edilmez; vakfedenin şartlarına uyulması gerektiği için şart değiştirilemez', ['Kabul edilir, çünkü mütevelli vakfın gerçek sahibidir ve şartları kendi takdirine göre değiştirebilir', 'Kabul edilir, çünkü şartlar yalnızca öneri niteliğindedir', 'Kabul edilir, çünkü padişah onayı yeterlidir ve şart önemsizdir'], 'Vakfedenin şartı bağlayıcı sayılırdı ("şart-ı vâkıf nass-ı şârî gibidir"); mütevelli şartları kendi isteğiyle değiştiremez, ancak kadı izniyle sınırlı uyarlamalar mümkündü.'),
  ('Bir caminin bakım ve personel giderlerinin karşılanması için vakıf adına işletilen dükkân, han ve hamam gibi gelir getiren mülklere ne ad verilirdi?', 'Akar', ['Mukataa', 'Hazine', 'Tapu'], 'Akar, vakfın sürekli gelir getiren mülkleridir; vakıflar kendi hizmetlerini çoğunlukla bu akarların gelirleriyle yürütürdü.'),
  ('Osmanlı\'da bir köylü, tımar sahibinin haksızlığını doğrudan padişaha duyurmak için yazılı dilekçe verdiğinde bu dilekçeye ne denirdi?', 'Arz-ı hâl (halk dilekçesi)', ['Telhis (sadrazamın padişaha raporu)', 'Tezkere', 'Ruznamçe'], 'Arz-ı hâl, halkın doğrudan padişaha ya da divana sunduğu dilekçedir; Osmanlı\'da şikâyetin merkeze taşınmasının aracıydı.'),
  ('Osmanlı medresesinde hocanın, öğrencisinin belirli bir kitabı ya da ilmi tamamladığını gösterdiği, ona öğretme yetkisi verdiği belgeye ne ad verilirdi?', 'İcazetname', ['Berat', 'Menşur', 'Hüccet'], 'İcazetname, öğrencinin bir ilim dalında yetkin olduğunu ve öğretebileceğini belirten hoca onayıdır; medrese eğitiminin kişiye dayalı niteliğini gösterir.'),
  ('Bir vilayetin veya vasal devletin yöneticisi, kendi adına İstanbul\'da bir temsilci bulunduruyor. Bu temsilciye ne denir?', 'Kapı kethüdası', ['Mütesellim', 'Kaymakam', 'Vali'], 'Kapı kethüdası, taşra yöneticisi veya vasal devlet adına merkezle ilişkileri yürüten ve başkentte bulunan temsilcidir.'),
  ('Nuruosmaniye (1755), Süleymaniye (1557) ve Sultanahmet (1616) camilerini eskiden yeniye doğru dizdiğimizde sıralama nasıl olur?', 'Süleymaniye, Sultanahmet, Nuruosmaniye', ['Sultanahmet, Süleymaniye, Nuruosmaniye sırasıyla', 'Nuruosmaniye, Süleymaniye, Sultanahmet', 'Süleymaniye, Nuruosmaniye, Sultanahmet'], 'Süleymaniye 16. yüzyıl, Sultanahmet 17. yüzyıl başı, Nuruosmaniye ise 18. yüzyıl ortasında tamamlanmıştır.'),
  ('Cizyenin zengin, orta halli ve yoksul gibi üç kademeye ayrılması hangi ilkeyi yansıtır?', 'Vergi yükünün ödeme gücüne göre değişmesi', ['Herkesin ödeme gücüne bakılmaksızın eşit miktarda vergi vermesi ve hiçbir indirim yapılmaması', 'Yalnızca zenginlerin vergi vermesi', 'Vergilerin kaldırılması'], 'Cizyenin ala, evsat ve edna olarak derecelendirilmesi, mükellefin gücüne göre kademeli vergilendirme yapılmasını sağlıyordu.'),
  ('Mimar Sinan\'ın İstanbul\'un su ihtiyacını karşılamak için yaptığı Kırkçeşme tesislerinin en bilinen su kemeri hangisidir?', 'Mağlova Kemeri', ['Bozdoğan Kemeri', 'Uzunköprü', 'Kırkçeşme Köprüsü'], 'Kırkçeşme su tesislerinin Kanuni dönemindeki yapımında Sinan\'ın en çarpıcı eseri Mağlova (Kovuk) Su Kemeri\'dir.'),
  ('Osmanlı donanmasının gemilerinin yapıldığı Tersane-i Âmire hangi su yolunun kıyısında yer alıyordu?', 'Haliç', ['İzmit Körfezi', 'Boğaz\'ın Anadolu yakası', 'Çanakkale Boğazı'], 'Tersane-i Âmire, Haliç\'te Kasımpaşa\'da bulunan, donanmanın gemi yapım ve bakım merkeziydi.'),
  ('Sultanahmet Camii çevresindeki Arasta Çarşısı\'nın temel yapılış amacı nedir?', 'Külliyenin giderlerini karşılayacak gelir sağlamak', ['Askerleri barındırmak ve seferde ordu için erzak toplamak', 'Mahkeme kurmak', 'Kütüphane açmak'], 'Arasta, caminin vakıf gelirini sağlamak amacıyla camiye bitişik yapılmış sıralı dükkânlardan oluşan çarşı bölümüdür.'),
  ('Aşağıdakilerden hangisi Enderun ağalıklarından biri değildir?', 'Muhtesib', ['Silahdar Ağa ve Rikâbdar', 'Dülbend Ağası ve Çuhadar', 'Çaşnigirbaşı ve Hazinedarbaşı'], 'Muhtesib çarşı ve esnaf denetimi yapan belediye görevlisidir; diğerleri padişahın yakınında hizmet eden Enderun ağalarıdır.'),
  ('Aşağıdakilerden hangisi Osmanlı\'da vakıf yoluyla yaptırılan hayır yapıları arasında yer almaz?', 'Tersane-i Âmire', ['Sebil ve çeşme', 'Darüşşifa ve imaret', 'Sıbyan mektebi ve kütüphane'], 'Tersane-i Âmire devletin donanma kuruluşudur; diğerleri vakıfça yaptırılan sosyal ve hayır yapılarıdır.'),
  ('Aşağıdakilerden hangisi 19. yüzyıl Osmanlı modernleşme kurumlarından biri değildir?', 'Enderun Mektebi', ['Mekteb-i Harbiye ve Tıphane-i Âmire', 'Şûrâ-yı Devlet ve Şehremaneti', 'Posta Nezareti ve Tercüme Odası'], 'Enderun Mektebi Fatih döneminden beri süren klasik saray okuludur; diğerleri 19. yüzyılda kurulan yeni kurumlardır.'),
  ('Aşağıdakilerden hangisi Osmanlı\'da ticari amaçlı bir yapı değildir?', 'Külhan', ['Han ve bedesten', 'Arasta ve kapan', 'Kervansaray ve çarşı'], 'Külhan hamamın ocağıdır; diğerleri alım satım, konaklama ve ticaretle ilgilidir.'),
  ('Osmanlı \'Âmire\' kurumları ve işlevlerine dair hangi eşleştirme hatalıdır?', 'Matbaa-i Âmire - gemi onarımı', ['Tersane-i Âmire - gemi yapımı', 'Darphane-i Âmire - para basımı', 'Tophane-i Âmire - top ve silah dökümü'], 'Matbaa-i Âmire resmî yayınları basan devlet matbaasıdır; gemi onarımı Tersane-i Âmire\'nin işidir.'),
  ('Osmanlı mahkeme ve vakıf görevlilerinin işlevleri aşağıda eşleştirilmiştir. Hangi eşleştirme hatalıdır?', 'Mütevelli - fetva hazırlamak', ['Muhtesib - çarşı ve ölçü denetimi yapmak', 'Kassam - mirası paylaştırmak', 'Muhzır - davalıyı mahkemeye getirmek'], 'Mütevelli vakıf yöneticisidir; fetva şeyhülislam ve müftünün işidir.'),
  ('Mimar ve eserlerin sıralandığı seçeneklerden hangisinde bir hata vardır?', 'Balyan ailesi - Selimiye Camii', ['Sinan - Süleymaniye Camii', 'Sedefkâr Mehmed Ağa - Sultanahmet Camii', 'Mimar Hayreddin - Mostar Köprüsü'], 'Selimiye Camii Sinan\'ın eseridir; Balyan ailesi ise 19. yüzyılda Dolmabahçe gibi yapıları inşa etmiştir.'),
  ('Padişahların şiirlerinde kullandığı mahlaslarla ilgili hangi bilgi yanlıştır?', 'Yavuz Sultan Selim - Nedîm', ['Fatih Sultan Mehmed - Avnî', 'Kanuni - Muhibbî', 'III. Selim - İlhamî'], 'Yavuz Sultan Selim, Selîmî mahlasıyla şiir yazmıştır; Nedîm ise Lale Devri şairidir.'),
  ('Osmanlı el sanatları ve tanımlarıyla ilgili ifadelerden hangisi yanlıştır?', 'Kündekâri - çini sanatı', ['Tezhip - kitap süsleme', 'Ebru - su yüzeyine desen', 'Hat - güzel yazı'], 'Kündekâri ahşabın geçmeli birleştirilmesiyle yapılan bir süsleme tekniğidir; çini ise ayrı bir sanat dalıdır.'),
  ('Osmanlı camilerinde mihrabın temel işlevi nedir?', 'Namaz kılınacak yönü (kıbleyi) göstermek', ['Hutbe okunacak yeri ve imamın duracağı yeri belirlemek', 'Müezzinin ezan okuduğu balkon olmak', 'Abdest alma yerini göstermek'], 'Mihrap, ibadet yönünü yani kıbleyi gösteren oyuk niş bölümdür; hutbe ise minberden okunur.'),
  ('Cami avlularındaki şadırvanın temel işlevi nedir?', 'Abdest almak için su sağlamak', ['Namaz vakitlerini göstermek ve ezan okumak', 'Cemaati toplamak', 'Cenaze yıkamak'], 'Şadırvan, Osmanlı camilerinin avlusunda abdest alınan çeşmeli havuz yapısıdır; mimari estetiğe de katkı sağlar.'),
  ('Osmanlı mimarisinde kubbeli olup önemli kişilerin gömüldüğü yapıya ne ad verilir?', 'Türbe', ['Şadırvan', 'Sebil', 'Cumba'], 'Türbe, padişah, vezir ve bilge kişilerin gömüldüğü kubbeli yapıdır; genellikle külliye içinde yer alır.'),
  ('İstanbul\'da Bizans\'tan kalan Hipodrom alanına Osmanlı döneminde ne ad verilmiştir?', 'Atmeydanı', ['Okmeydanı', 'Et Meydanı', 'Alay Meydanı'], 'Hipodrom, Osmanlı döneminde Atmeydanı olarak anılmış; şenlikler, cirit ve at yarışları burada yapılırdı.'),
  ('Osmanlı Devleti\'nin 1535\'te Fransa\'ya verdiği ticari ayrıcalıklar hangi padişah dönemine aittir?', 'Kanuni Sultan Süleyman (1520-1566)', ['Yavuz Sultan Selim (Mısır\'ın fatihi)', 'II. Bayezid', 'III. Murad'], '1535\'te Kanuni döneminde Fransa\'ya ticari ayrıcalıklar tanınmış, bu imtiyazlar sonraki dönemlerde diğer devletlere de verilmiştir.'),
  ('Osmanlı vakıf kütüphanelerinde kitapların genellikle dışarı verilmemesi ve yerinde okunması neyi amaçlıyordu?', 'Vakfedilen kitapların korunması ve kaybolmasının önlenmesini', ['Kitapların satılıp elde edilen gelirle yeni kitap alınmasını ve vakıf gelirlerinin artırılmasını', 'Kütüphanenin ücret almasını', 'Kitapların yurtdışına gönderilmesini'], 'Vakıf şartlarına göre kitaplar vakıf malı sayıldığından, korunması için ödünç verilmez, yerinde okutulurdu.'),
  ('Osmanlı camilerinde cuma hutbesini okuyan görevliye ne ad verilir?', 'Hatip', ['Kayyum', 'Müezzin', 'Kassam'], 'Hatip, cuma ve bayram hutbesini okuyan din görevlisidir; müezzin ise ezan okur, kayyum ise caminin bakımına bakar.'),
  ('19. yüzyılda Ramazan akşamlarında Karagöz, ortaoyunu ve meddah gösterilerinin yapıldığı İstanbul\'daki eğlence merkezine ne ad verilirdi?', 'Direklerarası (Şehzadebaşı)', ['Atmeydanı (Sultanahmet\'teki eski Hipodrom)', 'Okmeydanı', 'Kâğıthane'], 'Direklerarası, Şehzadebaşı\'nda Ramazan geceleri halkın tiyatro, meddah, ortaoyunu ve Karagöz izlediği eğlence merkeziydi.'),
  ('Osmanlı sarayında "harem" sözcüğü hangi anlamı taşır?', 'Yasak ve korunan yer', ['Alışveriş ve ticaret yapılan yer', 'Eğitim yeri', 'Askerî alan'], 'Harem, sözcük olarak "yasak, dokunulmaz" anlamındadır; sarayın padişahın ailesinin yaşadığı özel ve korunan bölümünü anlatır.'),
  ('Enderun ve Birun sözcükleri Osmanlı saray teşkilatında hangi anlamları ifade eder?', 'Enderun iç, Birun dış hizmetleri', ['Enderun dış hizmetler, Birun iç hizmetler anlamındadır', 'Her ikisi de askerî kışla', 'Her ikisi de hanedan'], 'Enderun "iç", Birun "dış" demektir; Enderun padişahın iç hizmetlerini ve saray okulunu, Birun ise devlet işleriyle ilgili dış hizmetleri anlatır.'),
  ('Barbaros Hayreddin Paşa\'nın türbesi İstanbul\'un hangi semtindedir?', 'Beşiktaş (İstanbul semti)', ['Eyüp (Ebû Eyyûb el-Ensârî\'nin semti)', 'Üsküdar', 'Fatih'], 'Barbaros Hayreddin Paşa\'nın türbesi Beşiktaş\'ta, adını taşıyan meydanın yakınında bulunur; deniz yönündeki yerleşim donanma geleneğini yansıtır.'),
  ('Enderun ile medrese arasındaki temel fark nedir?', 'Enderun devlet adamı ve saray görevlisi, medrese ilmiye mensubu yetiştirirdi', ['Enderun yalnızca kadınlara, medrese ise yalnızca erkeklere ve gayrimüslim çocuklara açıktı', 'Enderun halk eğitimi, medrese saray eğitimi veriyordu', 'İkisi de aynı amaçla kurulmuştu'], 'Enderun padişahın saray okuluydu ve devlet ile askerî yönetime adam yetiştirirdi; medreseler müderris, kadı ve imam gibi ilmiye mensupları yetiştirirdi.'),
  ('Osmanlı eğitim kurumlarından sıbyan mektebi ve medrese hangi bakımdan birbirinden ayrılır?', 'Sıbyan mektebi ilk öğretim, medrese ise yüksek öğretim düzeyindeydi', ['Sıbyan mektebi yalnızca bilim dersleri, medrese ise yalnızca sanat dersleri verirdi', 'Sıbyan mektebi askerî, medrese sivil okuldu', 'Sıbyan mektebi yalnızca kızlara açıktı'], 'Sıbyan mektebi okuma yazma ve temel dinî bilgileri öğreten ilk öğretim kurumuydu; medrese ise ileri düzey din ve ilim eğitimi verirdi.'),
  ('Osmanlı toplumunda bir tekke ile bir medresenin toplumsal görevleri hangi yönden birbirinden ayrılırdı?', 'Tekke tasavvuf eğitimi ve ibadet, medrese ise ilim eğitimi merkeziydi', ['Tekke yalnızca ticaret ve esnaf işlerine, medrese yalnızca askerî eğitime ayrılmıştı', 'Tekke saray, medrese orduya aitti', 'İkisi de aynı işlevi görürdü'], 'Tekke tarikat öğretisi, zikir ve sema gibi ibadetlerin yapıldığı yerdi; medrese ise fıkıh, kelam gibi ilimlerin okutulduğu eğitim kurumuydu.'),
  ('Han ve bedesten yapıları işlev bakımından nasıl ayrılır?', 'Han konaklama ve ticaret yeriyken, bedesten değerli malların saklandığı kapalı yapıydı', ['Han yalnızca askerî kışla, bedesten ise yalnızca dinî eğitim yapısı olarak kullanılırdı', 'Han hamam, bedesten çeşmeydi', 'İkisi de kışla olarak kullanılırdı'], 'Han tüccar ve yolcuların konakladığı, ticaret yapılan yerdi; bedesten ise kıymetli mallar için sağlam ve güvenli, kapalı bir ticaret yapısıydı.'),
  ('Kadı ile müftü arasındaki temel fark nedir?', 'Kadı yargılayıp karar verir, müftü hukuki görüş (fetva) bildirir', ['Kadı fetva verir, müftü ise davalara bakıp bağlayıcı hüküm vererek cezaları infaz eder', 'İkisi de aynı kararı verir', 'Kadı vergi toplar, müftü ordu komutasını yürütür'], 'Kadı davalara bakıp hüküm verir; müftü ise hukuki soruya yazılı görüş (fetva) verir ve bu görüş doğrudan bir yargı hükmü değildir.'),
  ('Osmanlı Devleti\'nde resmî yazışmalarda kullanılan dilin Arapça ve Farsça sözcükler bakımından zengin olmasının nedeni nedir?', 'Medrese eğitimi, din ve edebiyat geleneğinin Arapça ve Farsça ile şekillenmesi', ['Türkçenin resmen yasaklanması ve tüm devlet görevlilerinin yalnızca Arap kökenli olması', 'Devletin yalnızca Arap ve Farslardan oluşması', 'Alfabenin Latin olması'], 'Arapça din ve ilim, Farsça edebiyat ve saray kültürü dili olduğundan Osmanlı Türkçesi bu sözcüklerle zenginleşmiştir.'),
  ('Osmanlı sarayında padişahın sağlığıyla ilgilenen ve tüm hekimlerin başı olan görevli kimdir?', 'Hekimbaşı', ['Kapıcıbaşı', 'Çaşnigirbaşı', 'Muhzırbaşı'], 'Hekimbaşı, padişahın ve saray halkının sağlığından sorumlu, Osmanlı hekimlerinin başındaki görevliydi.'),
  ('Osmanlı mahallelerinde çocukların koyun ya da keçi bileğindeki kemikle oynadıkları geleneksel oyun hangisidir?', 'Aşık oyunu (çocuk oyunu)', ['Cirit (atlı süvari oyunu)', 'Satranç', 'Tavla'], 'Aşık oyunu, hayvan ayak bileği kemiğiyle oynanan, sokak ve mahalle oyunlarının yaygın bir örneğidir.'),
  ('Bir cami avlusunda cenaze namazı kılınacaktır. Cenaze nereye konulur?', 'Musalla taşı', ['Sadaka taşı', 'Mil taşı', 'Menzil taşı'], 'Musalla taşı, cenaze namazı için cenazenin konulduğu taş olup genellikle cami avlusunda veya mezarlık girişinde bulunur.'),
  ('Bir öğrenci "Osmanlı vakıfları yalnızca dinî amaçlıydı" diyor. Hangi bilgi bu görüşü çürütür?', 'Vakıfların köprü, çeşme, darüşşifa ve kuş evi gibi sosyal yapıları da finanse etmesi', ['Vakıfların yalnızca cami yaptırıp imam ve müezzin maaşı ödemekle yetinmesi ve sosyal hizmet vermemesi', 'Vakıfların medrese kurması', 'Vakıfların imam maaşı ödemesi'], 'Vakıflar kamu hizmetlerini, sağlığı ve hayvan korumayı da üstlenmiş, toplumsal hayatın geniş alanını kapsamıştır.'),
  ('Nurbanu Sultan\'ın vakfı olarak Mimar Sinan\'ın yaptığı, İstanbul\'daki tarihî hamam hangisidir?', 'Çemberlitaş Hamamı (Sinan eseri)', ['Cağaloğlu Hamamı (Sirkeci yakını)', 'Gedikpaşa Hamamı', 'Tahtakale Hamamı'], 'Çemberlitaş Hamamı, Sinan\'ın eseridir ve Nurbanu Sultan\'ın külliye vakfına gelir sağlamak için yapılmıştır.'),
  ('Hürrem Sultan Hamamı hangi iki ünlü yapının arasında bulunur?', 'Ayasofya ile Sultanahmet Camii', ['Süleymaniye Camii ile Beyazıt Camii arasındaki eski meydan', 'Fatih ile Eyüp Camii', 'Topkapı Sarayı ile Dolmabahçe'], 'Hürrem Sultan Hamamı, Sinan\'ın yaptığı çifte hamamdır ve Ayasofya ile Sultanahmet Camii arasında yer alır.'),
  ('İstanbul\'da birçok semtin (Fatih, Beyazıt, Süleymaniye, Laleli) adını camilerden veya külliyelerden alması hangi sonucu gösterir?', 'Külliyelerin çevrelerinde yeni yerleşim ve mahalle oluşturan merkezler olduğunu', ['Camilerin yalnızca ibadet edilen, çevresine hiçbir etki yapmayan ve kentten kopuk yapılar olduğunu', 'Semtlerin rastgele adlandırıldığını', 'Külliyelerin kentten uzak yapıldığını'], 'Külliyeler çevrelerinde çarşı, mahalle ve nüfus çekerek kent dokusunu şekillendirdiğinden semtler külliye adlarıyla anılmıştır.'),
  ('İstanbul\'daki Fatih Camii\'ni 1470\'te yapan mimar kimdir?', 'Atik Sinan', ['Mimar Sinan', 'Sedefkâr Mehmed Ağa', 'Mimar Hayreddin'], 'Fatih Camii\'nin mimarı Atik Sinan\'dır; ünlü Mimar Sinan\'dan yaklaşık bir asır önce yaşamıştır ve sık karıştırılır.'),
  ('Bir Osmanlı camisinde imam, cuma hutbesini merdivenli yüksek bir bölümden okuyor. Bu bölümün adı nedir?', 'Minber (hutbe kürsüsü)', ['Mihrap (kıbleyi gösteren niş)', 'Şerefe', 'Mahfil'], 'Minber, cuma ve bayram hutbesinin okunduğu merdivenli, yüksek bölümdür; mihrap ise kıble yönünü gösteren nişdir.'),
  ('Bir yolcu, yol kenarındaki küçük bir yapıdan ücretsiz su içiyor. Bu yapı Osmanlı\'da hangi addır?', 'Sebil', ['Şadırvan', 'Hamam', 'Bedesten'], 'Sebil, yoldan geçenlere ücretsiz su dağıtılan, çoğu zaman vakıf geliriyle ayakta tutulan küçük yapıdır.'),
];
